  "tutPtM6Text": "Durchsuchen Sie chronologische Sitzungsprotokolle mit Einzel- und Teampunkten, Abzeichen, Unterrichtszielen und Notizen.",
  "tutPtM7Title": "Klassenübersicht & Schülerdetails",
  "tutPtM7Text": "Überprüfen Sie kumulierte Schülerwerte, Verhältnisse, Trends und vorläufige Noten. Klicken Sie auf einen Schüler für Details oder rechtsklicken Sie zum Bearbeiten.",
  "tutPtR1Title": "Ziele & Bewertungsregeln",
  "tutPtR1Text": "Legen Sie Kriterien und automatische Punkteberechnungen für die Schülerbeteiligung fest.",
  "tutPtR2Title": "Geltungsbereich",
  "tutPtR2Text": "Wählen Sie, ob Regeln für alle Klassen oder speziell für die ausgewählte Gruppe gelten.",
  "tutPtR3Title": "Bewertungszeitraum",
  "tutPtR3Text": "Bestimmen Sie den Datumsbereich (alle Sitzungen, letzte Tage oder aktuelles Semester) für die Notenberechnung.",
  "tutPtR4Title": "Kriterien & Formeln",
  "tutPtR4Text": "Definieren Sie Schwellenwerte (Aufrufe, Nettopunkte, Anwesenheit, Abzeichen) oder Formeln zur Punktevergabe.",
  "tutPtR5Title": "Notenskala & Maximalnote",
  "tutPtR5Text": "Stellen Sie die Maximalnote (z.B. 20) ein und aktivieren Sie die proportionale Skalierung.",
  "tutPtR6Title": "Vorläufige Notenvorschau",
  "tutPtR6Text": "Sehen Sie berechnete Noten in Echtzeit, kopieren Sie diese in die Zwischenablage oder exportieren Sie sie ins Notenbuch.",
  "tutPtR7Title": "Vorlagen & Aktionen",
  "tutPtR7Text": "Speichern Sie Regeln als Vorlagen, laden Sie vorhandene Sets oder exportieren Sie Regeln als HTML/PDF.",
  "tutPtD1Title": "Schülerdetails & Kontext",
  "tutPtD1Text": "Zeigt den Schülernamen, die Klassengruppe und Sitzungsinformationen an.",
  "tutPtD2Title": "Punkte & Abzeichen anpassen",
  "tutPtD2Text": "Bearbeiten Sie Aufrufe, Plus-/Minuspunkte, Anwesenheit und Abzeichen für jede aufgezeichnete Sitzung.",
  "tutPtD3Title": "Lehrerbeobachtungen",
  "tutPtD3Text": "Erfassen Sie qualitative Rückmeldungen, Verhaltensnotizen und pädagogische Beobachtungen.",
  "tutPtD4Title": "Schülerdaten speichern",
  "tutPtD4Text": "Speichern Sie Ihre Anpassungen. Statistiken, Kennzahlen und vorläufige Noten werden sofort neu berechnet.",
