  "lcActWarmUpDesc": "Kurze Einstiegsaufgabe (3–5 Min.) zu Beginn der Stunde zur Aktivierung des Vorwissens und Einstimmung der Klasse.",
  "lcAct_warm_up_when": "Erste 5 Minuten; Begrüßungsritual, Wissensabruf, Stundeneinstieg.",
  "lcActDirectInstructionDesc": "Explizite Vermittlung neuer Inhalte durch die Lehrkraft, Demonstration von Lösungswegen oder Erläuterung von Konzepten (10–15 Min.).",
  "lcAct_direct_instruction_when": "Einführung neuer Lernziele, Regeln, Formeln oder Methoden.",
  "lcActGuidedPracticeDesc": "Schüler üben die neue Fertigkeit unter direkter Anleitung der Lehrkraft mit Zwischenschritten und sofortiger Rückmeldung.",
  "lcAct_guided_practice_when": "Direkt nach der Erarbeitung zur Festigung und Vermeidung von Fehlkonzepten.",
  "lcActIndependentWorkDesc": "Schüler bearbeiten Aufgaben, Texte oder Übungen eigenständig im eigenen Tempo ohne ständige Lehrkrafthilfe.",
  "lcAct_independent_work_when": "Nach dem angeleiteten Üben; ermöglicht der Lehrkraft gezielte Differenzierung.",
  "lcActGroupActivityDesc": "Kooperative Teamaufgabe zur Lösung komplexer Aufgaben, Erarbeitung von Projekten oder Experimenten mit verteilten Rollen.",
  "lcAct_group_activity_when": "Gruppenpuzzles, Projektarbeit, Experimente und mehrschrittige Aufgabenstellungen.",
  "lcActDiscussionDesc": "Strukturierter Meinungsaustausch, Debatte oder sokratischer Dialog zur Argumentation, Reflexion und Urteilsbildung.",
  "lcAct_discussion_when": "Ethische Fragestellungen, Textinterpretationen, Urteilsbildung und Sprechförderung.",
  "lcActAssessmentDesc": "Kurze formative Lernstandserhebung (z. B. Mini-Whiteboards, Blitzquiz), um das Verständnis vor dem Weiterschreiten zu prüfen.",
  "lcAct_assessment_when": "Zur Zwischenüberprüfung des Lernzuwachses vor dem nächsten Themenschwerpunkt.",
  "lcActPlenaryDesc": "Stundenabschluss (5–10 Min.) zur Sicherung der Kernergebnisse, Reflexion des Lernziels und Erhebung von Exit-Tickets.",
  "lcAct_plenary_when": "Letzte 5–10 Minuten zur nachhaltigen Ergebnissicherung.",
  "lcModeWholeClassDesc": "Alle Schüler arbeiten gemeinsam als eine Gesamtgruppe (z. B. gemeinsames Lesen, Einstiegsimpuls, Plenum-Brainstorming).",
  "lcMode_whole_class_when": "Gemeinsamer Bezugspunkt, Arbeitsaufträge an alle, Bild- oder Videoimpulse.",
  "lcModeTeacherLedDesc": "Lehrkraft steuert das Geschehen an der Tafel oder am Beamer, erklärt Zusammenhänge und moderiert Beiträge.",
  "lcMode_teacher_led_when": "Frontalphasen, Modellieren von Rechenwegen oder grammatischen Regeln.",
  "lcModeIndividualDesc": "Jeder Schüler arbeitet still und für sich allein am eigenen Platz zur Förderung von Konzentration und Eigenständigkeit.",
  "lcMode_individual_when": "Stille Lesephasen, Verfassen von Texten, Übungsaufgaben und Tests.",
  "lcModePairsDesc": "Zwei Schüler arbeiten als Tandem zusammen (Think-Pair-Share, Partnerkorrektur, Dialoge). Maximiert die Sprechzeit aller.",
  "lcMode_pairs_when": "Kurzer Murmelaustausch, Partnerfeedback, Einüben von Dialogen.",
  "lcModeSmallGroupsDesc": "Teams von 3 bis 4 Lernenden arbeiten kooperativ mit festen Rollen (Sprecher, Zeitwächter, Protokollant, Moderator).",
  "lcMode_small_groups_when": "Erstellung von Plakaten, Gruppenforschung, kollaborative Problemlösung.",
  "lcModeStationsDesc": "Der Raum ist in Lernstationen unterteilt; die Schüler wechseln zeitgesteuert zwischen verschiedenen Arbeitsbereichen.",
  "lcMode_stations_when": "Stationenlernen, naturwissenschaftliche Experimentierzirkel, Übungszirkel.",
